from __future__ import annotations

import pathlib
import re

try:
    import tomllib
except ModuleNotFoundError:  # pragma: no cover - exercised on Python 3.10.
    import tomli as tomllib

# Packages we look for across a deployment's declared dependencies. Every entry
# here must be individually detectable by `find_tracked_packages`.
TRACKED_PACKAGES: tuple[str, ...] = ("google-adk",)

# Only read up to roughly this many characters from a dependency file. Content
# beyond the cap is silently discarded so that pathologically large files can
# never blow up the deploy flow.
_MAX_FILE_SIZE = 5 * 1024 * 1024  # ~5 MB

# Leading `name[extras]<specifier>` portion of a PEP 508 requirement string.
_REQUIREMENT_RE = re.compile(
    r"^\s*([A-Za-z0-9][A-Za-z0-9._-]*)\s*(?:\[([^\]]*)\])?\s*(.*)$",
    re.DOTALL,
)


def _normalize(name: str) -> str:
    """Normalize a distribution name per PEP 503."""
    return re.sub(r"[-_.]+", "-", name).strip().lower()


def _read_capped(path: pathlib.Path) -> str | None:
    """Read up to `_MAX_FILE_SIZE` characters from `path`.

    Returns `None` when the file cannot be read. Anything past the cap is
    discarded, so a marker beyond it is never detected.
    """
    try:
        with path.open("r", encoding="utf-8", errors="ignore") as fp:
            return fp.read(_MAX_FILE_SIZE)
    except OSError:
        return None


def _match_requirement(requirement: str, package: str) -> str | None:
    """Return the version specifier for `package` within a requirement string.

    Returns the declared specifier (e.g. `>=0.5,<2`), `"unknown"` when the
    package is referenced without a specifier or only as an extra, or `None`
    when the requirement does not reference the package at all.
    """
    match = _REQUIREMENT_RE.match(requirement)
    if not match:
        return None
    name, extras, remainder = match.group(1), match.group(2) or "", match.group(3) or ""
    normalized = _normalize(package)

    if _normalize(name) == normalized:
        # Drop any environment marker (everything after ';').
        specifier = remainder.split(";", 1)[0].strip()
        return specifier if specifier else "unknown"

    for extra in extras.split(","):
        if _normalize(extra) == normalized:
            return "unknown"

    return None


def _scan_uv_lock(text: str, package: str) -> str | None:
    """Return the resolved version of `package` from `uv.lock` text, if present."""
    normalized = _normalize(package)
    for block in re.split(r"(?m)^\[\[package\]\]\s*$", text):
        name_match = re.search(r'(?m)^\s*name\s*=\s*"([^"]+)"', block)
        if not name_match or _normalize(name_match.group(1)) != normalized:
            continue
        version_match = re.search(r'(?m)^\s*version\s*=\s*"([^"]+)"', block)
        if version_match:
            return version_match.group(1)
    return None


def _pyproject_dependencies(text: str) -> list[str]:
    """Extract the `[project].dependencies` strings from pyproject.toml text."""
    try:
        data = tomllib.loads(text)
    except Exception:
        return []
    project = data.get("project")
    if not isinstance(project, dict):
        return []
    raw = project.get("dependencies")
    if not isinstance(raw, list):
        return []
    return [dep for dep in raw if isinstance(dep, str)]


def _scan_pyproject(text: str, package: str) -> str | None:
    for dependency in _pyproject_dependencies(text):
        result = _match_requirement(dependency, package)
        if result is not None:
            return result
    return None


def _scan_requirements(text: str, package: str) -> str | None:
    for raw_line in text.splitlines():
        line = raw_line.strip()
        if not line or line.startswith("#"):
            continue
        # Strip inline comments.
        line = line.split(" #", 1)[0].strip()
        if not line:
            continue
        result = _match_requirement(line, package)
        if result is not None:
            return result
    return None


def _scan_directory(directory: pathlib.Path) -> list[str]:
    """Return `package:version` strings for tracked packages found in `directory`.

    Precedence for each tracked package is `uv.lock` (resolved version) >
    `pyproject.toml` (declared specifier) > `requirements.txt` (declared
    constraint).
    """
    uv_lock = directory / "uv.lock"
    pyproject = directory / "pyproject.toml"
    requirements = directory / "requirements.txt"

    uv_text = _read_capped(uv_lock) if uv_lock.is_file() else None
    pyproject_text = _read_capped(pyproject) if pyproject.is_file() else None
    requirements_text = _read_capped(requirements) if requirements.is_file() else None

    results: list[str] = []
    for package in TRACKED_PACKAGES:
        version: str | None = None
        if uv_text is not None:
            version = _scan_uv_lock(uv_text, package)
        if version is None and pyproject_text is not None:
            version = _scan_pyproject(pyproject_text, package)
        if version is None and requirements_text is not None:
            version = _scan_requirements(requirements_text, package)
        if version is not None:
            results.append(f"{package}:{version}")
    return results


def find_tracked_packages(config: pathlib.Path, config_json: dict) -> list[str]:
    """Scan declared dependency directories for tracked packages.

    `config` is the path to the `langgraph.json` file; its parent directory is
    treated as the project root. Dependency paths in `config_json["dependencies"]`
    are resolved relative to that root. Returns a list of `package:specifier`
    strings from the first dependency path that yields any match, or an empty
    list when nothing is found.
    """
    project_root = pathlib.Path(config).resolve().parent
    dependencies = config_json.get("dependencies") or []

    for dependency in dependencies:
        if not isinstance(dependency, str):
            # Silently ignore non-string dependency entries.
            continue
        try:
            resolved = (project_root / dependency).resolve()
        except (OSError, ValueError):
            continue
        # Never scan a location outside the project root.
        if resolved != project_root and project_root not in resolved.parents:
            continue
        if not resolved.is_dir():
            continue
        results = _scan_directory(resolved)
        if results:
            return results

    return []
